<style scoped lang="scss" src="./hero-banner.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";

@Component
export default class HeroBanner extends Vue {
  @Prop({ type: String, default: "" }) image;

  hasSlot() {
    return Boolean(this.$slots.default);
  }
}
</script>

<template>
  <div class="HeroBanner" v-bind:style="{ backgroundImage: `url(${image})` }">
    <div class="HeroBanner__Content">
      <div v-if="hasSlot()" class="HeroBanner__Message">
        <slot />
      </div>
    </div>
  </div>
</template>
